create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path=public,pg_temp as $$ begin new.updated_at=now(); return new; end $$;
revoke all on function public.touch_updated_at() from public,anon,authenticated;
do $$ declare t text; begin for t in select unnest(array['categories','units','taxes','box_sizes','parties','products','warehouses','warehouse_stocks','stocks','purchases','purchase_items','sales','sale_items','stock_transfers','purchase_details','sale_details','purchase_returns','purchase_return_details','sale_returns','sale_return_details','medicine_types','manufacturers','purchase_orders','purchase_order_items','goods_received_notes','grn_items','quality_checks','supplier_payments','payment_schedules','aging_reports','expense_categories','income_categories','expenses','incomes','prescriptions','insurance_companies','insurance_policies','insurance_claims','loyalty_programs','loyalty_transactions','customer_interactions','batch_lots','recall_events','traceability_logs','stock_audits']) loop execute format('drop trigger if exists %I on public.%I',t||'_updated_at',t); execute format('create trigger %I before update on public.%I for each row execute function public.touch_updated_at()',t||'_updated_at',t); end loop; end $$;